// This file exercises Executor.CreateRun's full loop against a real
// Postgres (via testcontainers), mirroring internal/repo/repo_test.go's
// in-package pattern. The behavior-level coverage of CreateRun already
// lives in tests/integration/create_run_executor_test.go (built behind
// //go:build integration) — that suite is authoritative for the exact
// termination-reason contracts. This file exists so `go test ./...`
// (no build tag), which is what the coverage gate actually runs,
// exercises internal/execution's non-pure logic too, rather than that
// coverage living only behind -tags=integration.

// execDBOutboxStub mirrors repo_test.go's dbOutboxStub.
type execDBOutboxStub struct{}

func (execDBOutboxStub) AddEvent(ctx context.Context, tx pgx.Tx, subject, msgID string, msg proto.Message) error {
	body, err := proto.Marshal(msg)
	if err != nil {
		return err
	}
	_, err = tx.Exec(ctx,
		`INSERT INTO agents.event_outbox (subject, msg_id, payload) VALUES ($1, $2, $3) ON CONFLICT (msg_id) DO NOTHING`,
		subject, msgID, body,
	)
	return err
}

func startExecutorTestPostgres(t *testing.T) *platformdb.Pool {
	t.Helper()
	if testing.Short() {
		t.Skip("skipping executor DB test in short mode")
	}
	ctx := context.Background()
	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("agents_execution_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = pgC.Terminate(ctx) })

	dsn, err := pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	_, file, _, _ := runtime.Caller(0)
	migrationsDir := filepath.Join(filepath.Dir(file), "..", "..", "migrations")

	gooseDB, err := goose.OpenDBWithDriver("pgx", dsn)
	require.NoError(t, err)
	require.NoError(t, goose.SetDialect("postgres"))
	goose.SetTableName("goose_db_version_agents")
	require.NoError(t, goose.Up(gooseDB, migrationsDir))

	_, err = gooseDB.Exec(`ALTER ROLE agents_app WITH LOGIN PASSWORD 'test_app'`)
	require.NoError(t, err)
	require.NoError(t, gooseDB.Close())

	u, err := url.Parse(dsn)
	require.NoError(t, err)
	u.User = url.UserPassword("agents_app", "test_app")

	pool, err := platformdb.NewPool(ctx, u.String())
	require.NoError(t, err)
	t.Cleanup(pool.Close)
	return pool
}

func execSeedTemplate(t *testing.T, pool *platformdb.Pool, key, namespace, kind string, allowedTools []string) {
	t.Helper()
	ctx := context.Background()
	err := pool.WithTxNoTenant(ctx, func(tx pgx.Tx) error {
		_, err := tx.Exec(ctx,
			`INSERT INTO agents.agent_templates
			   (key, namespace, display_name, description, system_prompt, allowed_tools, kind)
			 VALUES ($1, $2, $3, $4, $5, $6, $7)
			 ON CONFLICT (key) DO UPDATE SET allowed_tools = EXCLUDED.allowed_tools, kind = EXCLUDED.kind`,
			key, namespace, key+" display", key+" description", key+" system prompt", allowedTools, kind,
		)
		return err
	})
	require.NoError(t, err)
}

func execSeedAgent(t *testing.T, pool *platformdb.Pool, orgID, agentID uuid.UUID, templateKey string, tokenBudget, maxIterations, maxWallClockSecs int32) {
	t.Helper()
	ctx := auth.HeadersIntoContext(context.Background(), auth.Headers{TenantID: orgID.String()})
	err := pool.WithTx(ctx, func(tx pgx.Tx) error {
		_, err := tx.Exec(ctx,
			`INSERT INTO agents.agents
			   (id, org_id, template_key, name, token_budget, max_iterations, max_wall_clock_secs)
			 VALUES ($1, $2, $3, 'test agent', $4, $5, $6)`,
			agentID, orgID, templateKey, tokenBudget, maxIterations, maxWallClockSecs,
		)
		return err
	})
	require.NoError(t, err)
}

func execTenantCtx(orgID, userID uuid.UUID) context.Context {
	return auth.HeadersIntoContext(context.Background(), auth.Headers{TenantID: orgID.String(), UserID: userID.String()})
}

// scriptedExec is a minimal fake ToolExecutor for the DB-backed executor
// tests in this file.
type scriptedExec struct {
	mu    sync.Mutex
	steps []struct {
		call   ToolCall
		result ExecuteToolResult
	}
	next int
}

func (f *scriptedExec) NextCall(_ context.Context, _ repo.AgentsAgentRun, _ int) (ToolCall, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.steps[f.next].call, nil
}

func (f *scriptedExec) ExecuteTool(_ context.Context, _ string, _ map[string]any) (ExecuteToolResult, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	result := f.steps[f.next].result
	f.next++
	return result, nil
}

func TestCreateRun_DB_HappyPath_CompletesAndPersistsRunEvent(t *testing.T) {
	pool := startExecutorTestPostgres(t)
	keys, err := audit.NewEnvKeyProvider("test-v1:dGVzdC1hZ2VudHMtYXVkaXQtaG1hYy1rZXktMzItYiEh", "test-v1")
	require.NoError(t, err)

	r := repo.NewRepo(pool, execDBOutboxStub{}, keys)
	reg := registry.New(registry.Config{})
	fake := &scriptedExec{steps: []struct {
		call   ToolCall
		result ExecuteToolResult
	}{
		{call: ToolCall{ToolName: "search_documents", Args: map[string]any{"q": "x"}, TokensUsed: 5}, result: ExecuteToolResult{OK: true}},
		{call: ToolCall{Done: true}},
	}}
	ex := NewExecutor(r, reg, fake)

	execSeedTemplate(t, pool, "tmpl-db-happy", "clio", "specialist", []string{"search_documents"})
	orgID, agentID, userID := uuid.New(), uuid.New(), uuid.New()
	execSeedAgent(t, pool, orgID, agentID, "tmpl-db-happy", 100000, 25, 300)

	ctx := execTenantCtx(orgID, userID)
	run, err := ex.CreateRun(ctx, CreateRunInput{
		AgentID:      agentID,
		UserID:       userID,
		RunMode:      "autonomous",
		InputPayload: []byte(`{}`),
	})
	require.NoError(t, err)
	require.Equal(t, "completed", *run.TerminatedReason)
	require.Equal(t, int32(5), run.TokensUsed)
	require.Equal(t, int32(1), run.IterationsUsed)

	events, err := r.ListRunEvents(ctx, run.ID)
	require.NoError(t, err)
	require.Len(t, events, 1)
}

