// Package execution implements agents-svc's think→act→observe run loop
// (PRD §4.1, issue #1928): CreateRun inserts the initial agent_runs row
// and then drives the loop synchronously to a terminal state, applying
// the owning agent's token/iteration/wall-clock caps and its template's
// tool-kind permission rules.
package execution

import (
	"context"
	"encoding/json"
	"errors"
	"math"
	"slices"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/hitl"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// ErrAgentNotFound is returned when CreateRun's AgentID does not resolve
// to a row visible to the caller's tenant (missing, or hidden by RLS —
// the two are indistinguishable and both surface as NotFound).
var ErrAgentNotFound = errors.New("execution: agent not found")

// orchestratorDispatchToolName is the tool whose successful calls count
// toward the orchestrator-exclusive dispatch-before-final-answer rule
// (issue #1931, PRD §8/§12).
const orchestratorDispatchToolName = "dispatch_agent"

// noSpecialistAppliesArg is the escape-hatch marker: an orchestrator's
// final (Done=true) call carrying Args[noSpecialistAppliesArg] == true is
// allowed to complete with zero dispatches (issue #1931's "no specialist
// applies" narrow exception).
const noSpecialistAppliesArg = "no_specialist_applies"

// ExecuteToolResult is the outcome of dispatching one tool call — the
// "act" step of think→act→observe.
type ExecuteToolResult struct {
	OK           bool
	ResultData   map[string]any
	ErrorCode    string
	ErrorMessage string
}

// ToolCall is what the "think" step decides to do next. Done=true means
// the run has no more work and should terminate with
// terminated_reason="completed". TokensUsed is the think+act round's
// token cost, added to the run's running total BEFORE the act step
// executes, so a round that would blow the budget is rejected without
// dispatching the tool call.
type ToolCall struct {
	Done       bool
	ToolName   string
	Args       map[string]any
	TokensUsed int32
}

// ToolExecutor is the injected dependency for both think (NextCall) and
// act (ExecuteTool). Production code will eventually back ExecuteTool
// with a gRPC ToolExecutorServiceClient dial to a vertical service (e.g.
// clio-svc) once one exists — that implementation is out of scope for
// #1928.
type ToolExecutor interface {
	NextCall(ctx context.Context, run repo.AgentsAgentRun, iteration int) (ToolCall, error)
	ExecuteTool(ctx context.Context, toolName string, args map[string]any) (ExecuteToolResult, error)
}

// HITLConfig configures the HITL wiring installed by WithHITL.
type HITLConfig struct {
	// ConcurrencyCapPerOrg bounds how many runs an org may have in flight
	// at once (issue #1929, scope decision 5). Ignored when sem is nil.
	ConcurrencyCapPerOrg int64
}

// Executor drives the think→act→observe loop over a *repo.Repo and
// *registry.Registry, dispatching tool calls through an injected
// ToolExecutor. HITL wiring (cancel/semaphore/idempotency stores) is
// optional — see WithHITL.
type Executor struct {
	repo  *repo.Repo
	reg   *registry.Registry
	tools ToolExecutor

	cancel hitl.CancelStore
	sem    hitl.SemaphoreStore
	idem   hitl.IdempotencyStore
	hcfg   HITLConfig
}

// NewExecutor constructs an Executor with no HITL wiring: cancellation
// never fires, no concurrency cap is enforced, and pausing for
// confirmation still works (it depends only on registry.Tool, not on any
// store), but ConfirmPendingCall/CancelRun should not be called against
// an Executor built this way in production (they degrade to no-ops on
// idempotency, since idem is nil — see checkIdempotent).
func NewExecutor(r *repo.Repo, reg *registry.Registry, tools ToolExecutor) *Executor {
	return &Executor{repo: r, reg: reg, tools: tools}
}

// Repo returns the *repo.Repo the executor was constructed with, for
// callers that need read-only access alongside the loop (issue #1930's
// StreamRunEvents replays repo.ListRunEvents/GetRun directly rather than
// through the executor).
func (e *Executor) Repo() *repo.Repo {
	return e.repo
}

// WithHITL installs the three NATS-KV-backed HITL stores (issue #1929)
// onto e and returns e (builder-style, mutates in place). Passing nil
// stores/cfg fields makes the corresponding check a no-op:
//   - cancel == nil: cancellation polling never fires.
//   - sem == nil: no concurrency cap is enforced.
//   - idem == nil: ConfirmPendingCall/CancelRun always treat the call as
//     new (no replay detection).
//
// Existing #1928 callers that never call WithHITL are completely
// unaffected.
func (e *Executor) WithHITL(cancel hitl.CancelStore, sem hitl.SemaphoreStore, idem hitl.IdempotencyStore, cfg HITLConfig) *Executor {
	e.cancel = cancel
	e.sem = sem
	e.idem = idem
	e.hcfg = cfg
	return e
}

// CreateRunInput carries the caller-supplied fields for CreateRun.
type CreateRunInput struct {
	AgentID      uuid.UUID
	UserID       uuid.UUID
	ChatID       uuid.UUID // uuid.Nil when unset
	RunMode      string    // "interactive" | "autonomous"
	InputPayload []byte    // raw JSON, non-nil (NOT NULL column)
}

// runEventPayload is the JSON shape persisted to run_events per
// completed iteration — the observe step's record of what was decided
// and what came back.
type runEventPayload struct {
	ToolName     string         `json:"tool_name"`
	Args         map[string]any `json:"args"`
	OK           bool           `json:"ok"`
	ResultData   map[string]any `json:"result_data,omitempty"`
	ErrorCode    string         `json:"error_code,omitempty"`
	ErrorMessage string         `json:"error_message,omitempty"`
}

// pendingCallPayload is the JSON shape persisted to agent_runs.pending_call
// when the loop pauses for confirmation (issue #1929, scope decision 4).
// PausedAt is embedded here (rather than a new column) so
// ConfirmPendingCall can compute the confirmation-timeout elapsed time
// without any schema change.
type pendingCallPayload struct {
	ToolName   string         `json:"tool_name"`
	Args       map[string]any `json:"args"`
	TokensUsed int32          `json:"tokens_used"`
	PausedAt   time.Time      `json:"paused_at"`
}

// CreateRun inserts the initial agent_runs row (status="running"), then
// drives the think→act→observe loop synchronously (no goroutine/streaming
// — that is #1930's StreamRunEvents scope) until it reaches a terminal
// state OR pauses for confirmation, persisting one run_event per
// completed iteration, and returns the run's post-image (terminal, or
// awaiting_confirmation).
//
// When a HITLConfig with sem != nil is installed (WithHITL), a per-org
// concurrency slot is acquired immediately after the row insert, before
// the loop starts; on failure the run is finalized immediately (zero
// iterations/tokens) with terminated_reason="concurrency_cap" rather than
// failing the RPC (issue #1929, scope decision 5).
//
// Per-iteration loop shape (see runLoop): wall-clock/iteration caps,
// cancellation poll, think (NextCall), budget check, tool-permission
// check, confirmation-required pause, act (ExecuteTool), observe
// (AppendRunEvent).
func (e *Executor) CreateRun(ctx context.Context, in CreateRunInput) (repo.AgentsAgentRun, error) {
	agent, err := e.repo.GetAgent(ctx, in.AgentID)
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}
	if agent.ID == uuid.Nil {
		return repo.AgentsAgentRun{}, observability.Wrap(observability.CodeNotFound, "GetAgent", ErrAgentNotFound)
	}

	tmpl, err := e.repo.GetAgentTemplateByKey(ctx, agent.TemplateKey)
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}

	h := auth.HeadersFromContext(ctx)
	orgID, err := uuid.Parse(h.TenantID)
	if err != nil {
		return repo.AgentsAgentRun{}, observability.Wrap(observability.CodeForbidden, "invalid tenant id", err)
	}

	var chatID pgtype.UUID
	if in.ChatID != uuid.Nil {
		chatID = pgtype.UUID{Bytes: in.ChatID, Valid: true}
	}

	run, err := e.repo.CreateRun(ctx, repo.CreateRunParams{
		OrgID:        orgID,
		AgentID:      in.AgentID,
		UserID:       in.UserID,
		ChatID:       chatID,
		RunMode:      in.RunMode,
		InputPayload: in.InputPayload,
	})
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}

	if e.sem != nil {
		acquired, err := e.sem.Acquire(ctx, run.OrgID.String(), e.hcfg.ConcurrencyCapPerOrg)
		if err != nil {
			return repo.AgentsAgentRun{}, err
		}
		if !acquired {
			return e.finalize(ctx, run, "concurrency_cap", 0, 0, 0)
		}
	}

	start := time.Now()
	return e.runLoopReleasingSemOnError(ctx, run, agent, tmpl, 0, 0, start, nil)
}

// runLoopReleasingSemOnError calls runLoop and, when a HITL semaphore is
// installed and runLoop returns an infra-level error (a path that bypasses
// finalize entirely — finalize already releases the slot on every terminal
// path, including error's own "error" reason), releases the org's
// concurrency slot before propagating the error. Without this, an infra
// failure mid-loop (a NextCall/ExecuteTool/AppendRunEvent/cancel-store
// error) would abandon the run without ever freeing its slot, and the
// semaphore bucket has no TTL to reclaim it.
func (e *Executor) runLoopReleasingSemOnError(
	ctx context.Context,
	run repo.AgentsAgentRun,
	agent repo.AgentsAgent,
	tmpl repo.AgentsAgentTemplate,
	tokensUsed, iterationsUsed int32,
	start time.Time,
	resumeCall *ToolCall,
) (repo.AgentsAgentRun, error) {
	out, err := e.runLoop(ctx, run, agent, tmpl, tokensUsed, iterationsUsed, start, resumeCall)
	if err != nil && e.sem != nil {
		_ = e.sem.Release(ctx, run.OrgID.String())
	}
	return out, err
}

// runLoop drives the think→act→observe loop shared by CreateRun (fresh
// start, resumeCall=nil) and ConfirmPendingCall (resumes from the
// persisted pending call — approve executes it and continues the loop;
// reject skips it and continues the loop without dispatching it).
//
// Per-iteration order: wall-clock/iteration cap check, cancellation poll
// (only when e.cancel != nil), think (tools.NextCall — skipped for the
// very first resumed iteration when resumeCall != nil), budget check,
// tool-permission check, confirmation-required pause, act
// (tools.ExecuteTool), observe (repo.AppendRunEvent).
func (e *Executor) runLoop(
	ctx context.Context,
	run repo.AgentsAgentRun,
	agent repo.AgentsAgent,
	tmpl repo.AgentsAgentTemplate,
	tokensUsed, iterationsUsed int32,
	start time.Time,
	resumeCall *ToolCall,
) (repo.AgentsAgentRun, error) {
	first := true

	for {
		if capReason := capCheck(time.Since(start), agent.MaxWallClockSecs, iterationsUsed, agent.MaxIterations); capReason != "" {
			return e.finalize(ctx, run, capReason, tokensUsed, iterationsUsed, time.Since(start))
		}

		if e.cancel != nil {
			cancelled, err := e.cancel.IsCancelled(ctx, run.ID.String())
			if err != nil {
				return repo.AgentsAgentRun{}, err
			}
			if cancelled {
				return e.finalize(ctx, run, "user_canceled", tokensUsed, iterationsUsed, time.Since(start))
			}
		}

		var call ToolCall
		if first && resumeCall != nil {
			// Resuming from a pending call — the "think" step already
			// happened (that's what produced the pending call in the
			// first place); do not ask NextCall again for this iteration.
			call = *resumeCall
		} else {
			var err error
			call, err = e.tools.NextCall(ctx, run, int(iterationsUsed))
			if err != nil {
				return repo.AgentsAgentRun{}, err
			}
		}
		first = false

		if call.Done {
			if tmpl.Kind == "orchestrator" && !isEscapeHatch(call.Args) {
				events, err := e.repo.ListRunEvents(ctx, run.ID)
				if err != nil {
					return repo.AgentsAgentRun{}, err
				}
				dispatched, err := hasSuccessfulDispatch(events)
				if err != nil {
					return repo.AgentsAgentRun{}, err
				}
				if !dispatched {
					return e.finalize(ctx, run, "no_dispatch_before_final_answer", tokensUsed, iterationsUsed, time.Since(start))
				}
			}
			return e.finalize(ctx, run, "completed", tokensUsed, iterationsUsed, time.Since(start))
		}

		if budgetExceeded(tokensUsed, call.TokensUsed, agent.TokenBudget) {
			return e.finalize(ctx, run, "budget_exceeded", tokensUsed, iterationsUsed, time.Since(start))
		}

		tool, ok := e.reg.ToolByName(call.ToolName)
		if !ok {
			return e.finalize(ctx, run, "error", tokensUsed, iterationsUsed, time.Since(start))
		}
		if !registry.IsToolPermittedForKind(tool, tmpl.Kind) {
			return e.finalize(ctx, run, "agent_not_permitted", tokensUsed, iterationsUsed, time.Since(start))
		}
		// Dispatch-time enforcement of the template's own allowed_tools
		// (issue #2422): validateTemplate only checks this list at
		// template save time. Without re-checking it here, "think" is
		// free to name any tool that merely exists and matches the
		// template's kind, regardless of what that specific template's
		// allowed_tools actually lists — harmless only so long as
		// NoopToolExecutor is wired, since ExecuteTool is never reached.
		// A live ToolExecutor makes that an escape from the allowlist a
		// human explicitly set on the template, so this must fail closed.
		if !slices.Contains(tmpl.AllowedTools, call.ToolName) {
			return e.finalize(ctx, run, "tool_not_allowed", tokensUsed, iterationsUsed, time.Since(start))
		}

		// resumeCall is only honored for the ExecuteTool dispatch on the
		// very first (resumed) iteration; a fresh NextCall result on any
		// later iteration always dispatches ExecuteTool, even if the tool
		// requires confirmation — resumeCall != nil is what distinguishes
		// "we already paused and got an answer for this exact call" from
		// "this is a brand-new decision that must pause again."
		if resumeCall == nil && tool.RequiresConfirmation {
			paused, err := e.pauseForConfirmation(ctx, run, call)
			if err != nil {
				return repo.AgentsAgentRun{}, err
			}
			return paused, nil
		}
		resumeCall = nil

		result, err := e.tools.ExecuteTool(ctx, call.ToolName, call.Args)
		if err != nil {
			return repo.AgentsAgentRun{}, err
		}

		payload, err := json.Marshal(runEventPayload{
			ToolName:     call.ToolName,
			Args:         call.Args,
			OK:           result.OK,
			ResultData:   result.ResultData,
			ErrorCode:    result.ErrorCode,
			ErrorMessage: result.ErrorMessage,
		})
		if err != nil {
			return repo.AgentsAgentRun{}, observability.Wrap(observability.CodeInternal, "marshal run event payload", err)
		}

		if _, err := e.repo.AppendRunEvent(ctx, repo.AppendRunEventParams{
			RunID:     run.ID,
			OrgID:     run.OrgID,
			EventType: "tool_call",
			Payload:   payload,
		}); err != nil {
			return repo.AgentsAgentRun{}, err
		}

		tokensUsed += call.TokensUsed
		iterationsUsed++
	}
}

// pauseForConfirmation persists the pending call (with a paused_at
// timestamp embedded for the later confirmation-timeout check) and
// returns the run's awaiting_confirmation post-image, without dispatching
// ExecuteTool. It does NOT append a run_event — the pause is recorded
// entirely in agent_runs.pending_call; only an actually-executed tool
// call (after approve) produces a run_event, so run_events stays a
// record of what was DONE, not what was merely proposed.
func (e *Executor) pauseForConfirmation(ctx context.Context, run repo.AgentsAgentRun, call ToolCall) (repo.AgentsAgentRun, error) {
	payload, err := json.Marshal(pendingCallPayload{
		ToolName:   call.ToolName,
		Args:       call.Args,
		TokensUsed: call.TokensUsed,
		PausedAt:   time.Now(),
	})
	if err != nil {
		return repo.AgentsAgentRun{}, observability.Wrap(observability.CodeInternal, "marshal pending call payload", err)
	}

	return e.repo.PauseRunForConfirmation(ctx, run.ID, payload)
}

// ConfirmPendingCall resumes a run paused for confirmation (issue #1929).
// approve=true executes the pending call then continues the loop; false
// aborts ONLY the pending call (no ExecuteTool dispatch, no run_event)
// and continues the loop, asking NextCall again. A confirmation arriving
// after the owning agent's confirmation_timeout_secs has elapsed since
// the pause terminates the run with terminated_reason="confirmation_timeout"
// regardless of approve. Idempotent: a replayed call (same run, same
// pause) returns the run's current state without re-executing/re-aborting.
func (e *Executor) ConfirmPendingCall(ctx context.Context, runID uuid.UUID, approve bool) (repo.AgentsAgentRun, error) {
	run, err := e.repo.GetRun(ctx, runID)
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}

	var pending pendingCallPayload
	if err := json.Unmarshal(run.PendingCall, &pending); err != nil {
		return repo.AgentsAgentRun{}, observability.Wrap(observability.CodeInternal, "unmarshal pending call payload", err)
	}

	if e.idem != nil {
		isNew, err := e.idem.MarkIfNew(ctx, "confirm:"+runID.String()+":"+pending.PausedAt.Format(time.RFC3339Nano))
		if err != nil {
			return repo.AgentsAgentRun{}, err
		}
		if !isNew {
			return e.repo.GetRun(ctx, runID)
		}
	}

	agent, err := e.repo.GetAgent(ctx, run.AgentID)
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}
	tmpl, err := e.repo.GetAgentTemplateByKey(ctx, agent.TemplateKey)
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}

	// The timeout only terminates the run when approve=true — an explicit
	// reject is honored even if it arrives after confirmation_timeout_secs,
	// since a reject that continues the loop (asking NextCall again) is
	// never ambiguous with an unanswered timeout the way a late approve is.
	elapsed := time.Since(pending.PausedAt)
	if approve && elapsed.Seconds() > float64(agent.ConfirmationTimeoutSecs) {
		return e.finalize(ctx, run, "confirmation_timeout", run.TokensUsed, run.IterationsUsed, elapsed)
	}

	if _, err := e.repo.ResumeRunAfterConfirmation(ctx, runID); err != nil {
		return repo.AgentsAgentRun{}, err
	}

	var resumeCall *ToolCall
	if approve {
		resumeCall = &ToolCall{ToolName: pending.ToolName, Args: pending.Args, TokensUsed: pending.TokensUsed}
	}
	// approve=false: resumeCall stays nil, so runLoop asks NextCall fresh
	// for the next decision — the rejected call is never dispatched.

	start := time.Now().Add(-time.Duration(run.ElapsedSeconds) * time.Second)
	return e.runLoopReleasingSemOnError(ctx, run, agent, tmpl, run.TokensUsed, run.IterationsUsed, start, resumeCall)
}

// CancelRun requests cancellation of a run (issue #1929). A run that is
// currently paused for confirmation (genuinely at rest — no in-flight
// loop to poll anything) is finalized immediately and synchronously to
// "user_canceled". A run whose loop is (synchronously, in another
// in-flight call) still executing has its cancel flag set for that
// loop's next per-iteration poll to observe. Idempotent: a replayed call
// for the same run returns its current state without re-cancelling.
func (e *Executor) CancelRun(ctx context.Context, runID uuid.UUID) (repo.AgentsAgentRun, error) {
	run, err := e.repo.GetRun(ctx, runID)
	if err != nil {
		return repo.AgentsAgentRun{}, err
	}

	if e.idem != nil {
		isNew, err := e.idem.MarkIfNew(ctx, "cancel:"+runID.String())
		if err != nil {
			return repo.AgentsAgentRun{}, err
		}
		if !isNew {
			return e.repo.GetRun(ctx, runID)
		}
	}

	if run.AwaitingConfirmation {
		return e.finalize(ctx, run, "user_canceled", run.TokensUsed, run.IterationsUsed, time.Duration(run.ElapsedSeconds)*time.Second)
	}

	if e.cancel != nil {
		if err := e.cancel.Cancel(ctx, runID.String()); err != nil {
			return repo.AgentsAgentRun{}, err
		}
	}
	return run, nil
}

// capCheck reports the terminated_reason for the first cap that fires,
// or "" if neither cap has fired yet. Wall-clock is checked before
// iteration count, matching the loop's cap-check order.
func capCheck(elapsed time.Duration, maxWallClockSecs int32, iterationsUsed, maxIterations int32) string {
	if elapsed.Seconds() > float64(maxWallClockSecs) {
		return "time_cap"
	}
	if iterationsUsed >= maxIterations {
		return "iteration_cap"
	}
	return ""
}

// budgetExceeded reports whether dispatching a call costing callTokens
// would push tokensUsed over tokenBudget.
func budgetExceeded(tokensUsed, callTokens, tokenBudget int32) bool {
	return tokensUsed+callTokens > tokenBudget
}

// isEscapeHatch reports whether a Done call carries the narrow
// "no specialist applies" marker (issue #1931), which excuses an
// orchestrator run from the dispatch-before-final-answer rule.
func isEscapeHatch(args map[string]any) bool {
	v, ok := args[noSpecialistAppliesArg]
	if !ok {
		return false
	}
	b, ok := v.(bool)
	return ok && b
}

// hasSuccessfulDispatch reports whether events contains at least one
// successful orchestratorDispatchToolName tool_call — the condition an
// orchestrator run must satisfy before emitting a final answer, absent
// the escape hatch (issue #1931).
func hasSuccessfulDispatch(events []repo.AgentsRunEvent) (bool, error) {
	for _, ev := range events {
		if ev.EventType != "tool_call" {
			continue
		}
		var payload runEventPayload
		if err := json.Unmarshal(ev.Payload, &payload); err != nil {
			return false, observability.Wrap(observability.CodeInternal, "unmarshal run event payload", err)
		}
		if payload.ToolName == orchestratorDispatchToolName && payload.OK {
			return true, nil
		}
	}
	return false, nil
}

// statusForTerminatedReason maps a terminated_reason to the DB status
// column value: "completed" for a clean finish, "error" for every other
// reason — there is no RunStatus enum value for
// "budget_exceeded"/"iteration_cap"/"time_cap", so those all bucket into
// ERROR (the terminated_reason column is what actually distinguishes
// them).
func statusForTerminatedReason(reason string) string {
	if reason == "completed" {
		return "completed"
	}
	return "error"
}

// finalize persists the run's terminal state (and its audit twin, in the
// same tx) via repo.FinalizeRun. Every terminated_reason other than
// "completed" gets a DB status of "error" — there is no RunStatus enum
// value for "budget_exceeded"/"iteration_cap"/"time_cap", so those all
// bucket into ERROR (the terminated_reason column is what actually
// distinguishes them).
func (e *Executor) finalize(ctx context.Context, run repo.AgentsAgentRun, reason string, tokensUsed, iterationsUsed int32, elapsed time.Duration) (repo.AgentsAgentRun, error) {
	status := statusForTerminatedReason(reason)
	terminatedReason := reason

	out, err := e.repo.FinalizeRun(ctx, repo.UpdateRunParams{
		ID:               run.ID,
		Status:           status,
		TerminatedReason: &terminatedReason,
		TokensUsed:       tokensUsed,
		IterationsUsed:   iterationsUsed,
		ElapsedSeconds:   int32(math.Round(elapsed.Seconds())),
		OutputPayload:    nil,
	})
	if e.sem != nil {
		// Release unconditionally for every terminal reason (including
		// concurrency_cap itself — a no-op there since nothing was
		// acquired for THIS run) so a slot never leaks. Best-effort: a
		// release failure does not override the FinalizeRun result/error
		// the caller is waiting on.
		_ = e.sem.Release(ctx, run.OrgID.String())
	}
	return out, err
}


