package execution

import (
	"context"
	"encoding/json"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// TestCapCheck covers the pure cap-check arithmetic exercised by
// CreateRun's loop: wall-clock cap checked before iteration cap, exactly
// max_iterations iterations allowed (not one over), and no cap firing
// mid-budget.
func TestCapCheck(t *testing.T) {
	tests := []struct {
		name             string
		elapsed          time.Duration
		maxWallClockSecs int32
		iterationsUsed   int32
		maxIterations    int32
		want             string
	}{
		{
			name:             "neither cap fires",
			elapsed:          1 * time.Second,
			maxWallClockSecs: 300,
			iterationsUsed:   0,
			maxIterations:    25,
			want:             "",
		},
		{
			name:             "wall clock cap fires",
			elapsed:          2 * time.Second,
			maxWallClockSecs: 1,
			iterationsUsed:   0,
			maxIterations:    25,
			want:             "time_cap",
		},
		{
			name:             "wall clock exactly at the limit does not fire",
			elapsed:          1 * time.Second,
			maxWallClockSecs: 1,
			iterationsUsed:   0,
			maxIterations:    25,
			want:             "",
		},
		{
			name:             "iteration cap fires once iterations_used equals the max",
			elapsed:          0,
			maxWallClockSecs: 300,
			iterationsUsed:   2,
			maxIterations:    2,
			want:             "iteration_cap",
		},
		{
			name:             "iteration cap does not fire one iteration short of the max",
			elapsed:          0,
			maxWallClockSecs: 300,
			iterationsUsed:   1,
			maxIterations:    2,
			want:             "",
		},
		{
			name:             "wall clock cap takes precedence over iteration cap",
			elapsed:          2 * time.Second,
			maxWallClockSecs: 1,
			iterationsUsed:   2,
			maxIterations:    2,
			want:             "time_cap",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := capCheck(tt.elapsed, tt.maxWallClockSecs, tt.iterationsUsed, tt.maxIterations)
			assert.Equal(t, tt.want, got)
		})
	}
}

// TestBudgetExceeded covers the running-total-plus-call-cost budget
// arithmetic: a call that would push tokens_used strictly over the
// budget is rejected; a call landing exactly on the budget is not.
func TestBudgetExceeded(t *testing.T) {
	tests := []struct {
		name        string
		tokensUsed  int32
		callTokens  int32
		tokenBudget int32
		want        bool
	}{
		{name: "well under budget", tokensUsed: 0, callTokens: 10, tokenBudget: 100, want: false},
		{name: "lands exactly on budget", tokensUsed: 90, callTokens: 10, tokenBudget: 100, want: false},
		{name: "one token over budget", tokensUsed: 91, callTokens: 10, tokenBudget: 100, want: true},
		{name: "single call already exceeds an empty budget", tokensUsed: 0, callTokens: 20, tokenBudget: 10, want: true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := budgetExceeded(tt.tokensUsed, tt.callTokens, tt.tokenBudget)
			assert.Equal(t, tt.want, got)
		})
	}
}

// TestToolPermitted covers the tool-permission branch as executor.go
// evaluates it inline: an unfound tool is never permitted, and a found
// tool defers to registry.IsToolPermittedForKind (orchestrator-only
// tools denied to specialists, everything else permitted for both
// kinds).
func TestToolPermitted(t *testing.T) {
