// pending_call.paused_at directly in Postgres so it appears to have
// paused `age` ago. ConfirmPendingCall's confirmation-timeout check
// computes elapsed = time.Since(pending.PausedAt) purely from that
// stored value — the pause itself is already synchronous by the time
// CreateRun returns (AwaitingConfirmation=true), so there is no async
// worker to race here. Backdating the stored timestamp makes the test
// deterministic and fast instead of racing a fixed sleep against a
// real-time deadline.
func backdatePendingCallPausedAt(t *testing.T, ctx context.Context, pool *platformdb.Pool, runID uuid.UUID, age time.Duration) {
	t.Helper()
	pausedAt := time.Now().Add(-age).Format(time.RFC3339Nano)
	err := pool.WithTx(ctx, func(tx pgx.Tx) error {
		_, err := tx.Exec(ctx,
			`UPDATE agents.agent_runs
			 SET pending_call = jsonb_set(pending_call, '{paused_at}', to_jsonb($1::text))
			 WHERE id = $2`,
			pausedAt, runID,
		)
		return err
	})
	require.NoError(t, err)
}

