	ctx := execTenantCtx(orgID, uuid.New())
	_, err := f.ex.CreateRun(ctx, CreateRunInput{AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`)})
	require.Error(t, err)

	require.Equal(t, int64(0), f.sem.counts[orgID.String()])

	// The freed slot is immediately usable by a fresh run for the same org.
	ok, err := f.sem.Acquire(context.Background(), orgID.String(), 1)
	require.NoError(t, err)
	require.True(t, ok)
}


