// scriptedExec is a minimal fake ToolExecutor for the DB-backed executor
// tests in this file.
type scriptedExec struct {
	mu    sync.Mutex
	steps []struct {
		call   ToolCall
		result ExecuteToolResult
	}
	next int
}

func (f *scriptedExec) NextCall(_ context.Context, _ repo.AgentsAgentRun, _ int) (ToolCall, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.steps[f.next].call, nil
}

func (f *scriptedExec) ExecuteTool(_ context.Context, _ string, _ map[string]any) (ExecuteToolResult, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	result := f.steps[f.next].result
	f.next++
	return result, nil
}

