// against a real Postgres (via testcontainers), mirroring
// createrun_dbtest_test.go's pattern — same rationale: `go test ./...`
// (no build tag) is what the coverage gate actually runs, so this
// package's HITL logic needs coverage here too, not only behind
// -tags=integration (tests/integration/hitl_confirm_cancel_test.go is
// authoritative for the exact behavior contracts; this file just needs
// the code paths exercised).

// fakeCancelStore/fakeSemaphoreStore/fakeIdempotencyStore are minimal
// in-memory stand-ins for the hitl package's NATS-KV-backed
// implementations (which are exercised for real in
// internal/hitl/store_test.go and
// tests/integration/hitl_confirm_cancel_test.go) — plenty for exercising
// the Executor's own control flow without a NATS dependency in this
// package's tests.
type fakeCancelStore struct{ cancelled map[string]bool }

func newFakeCancelStore() *fakeCancelStore { return &fakeCancelStore{cancelled: map[string]bool{}} }

func (f *fakeCancelStore) Cancel(_ context.Context, runID string) error {
	f.cancelled[runID] = true
	return nil
}

func (f *fakeCancelStore) IsCancelled(_ context.Context, runID string) (bool, error) {
	return f.cancelled[runID], nil
}

type fakeSemaphoreStore struct{ counts map[string]int64 }

func newFakeSemaphoreStore() *fakeSemaphoreStore {
	return &fakeSemaphoreStore{counts: map[string]int64{}}
}

func (f *fakeSemaphoreStore) Acquire(_ context.Context, key string, max int64) (bool, error) {
	if f.counts[key] >= max {
		return false, nil
	}
	f.counts[key]++
	return true, nil
}

func (f *fakeSemaphoreStore) Release(_ context.Context, key string) error {
	if f.counts[key] > 0 {
		f.counts[key]--
	}
	return nil
}

type fakeIdempotencyStore struct{ seen map[string]bool }

func newFakeIdempotencyStore() *fakeIdempotencyStore {
	return &fakeIdempotencyStore{seen: map[string]bool{}}
}

func (f *fakeIdempotencyStore) MarkIfNew(_ context.Context, key string) (bool, error) {
	if f.seen[key] {
		return false, nil
	}
	f.seen[key] = true
	return true, nil
}

var _ hitl.CancelStore = (*fakeCancelStore)(nil)
var _ hitl.SemaphoreStore = (*fakeSemaphoreStore)(nil)
var _ hitl.IdempotencyStore = (*fakeIdempotencyStore)(nil)

