	run, err := f.ex.CreateRun(ctx, CreateRunInput{AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`)})
	require.NoError(t, err)
	require.NotNil(t, run.TerminatedReason)
	require.Equal(t, "concurrency_cap", *run.TerminatedReason)
	require.Equal(t, int32(0), run.IterationsUsed)
}

// pollCancelExec's NextCall sets the cancel flag on its FIRST call
// (simulating an out-of-band CancelRun arriving mid-loop, as the
// integration suite's hitlScriptedToolExecutor does), then serves its
// scripted steps — proving the flag is observed at the top of the NEXT
// iteration.
type pollCancelExec struct {
	steps  []ToolCall
	next   int
	cancel *fakeCancelStore
	fired  bool
}

func (f *pollCancelExec) NextCall(ctx context.Context, run repo.AgentsAgentRun, _ int) (ToolCall, error) {
	if !f.fired {
		f.fired = true
		if f.cancel != nil {
			_ = f.cancel.Cancel(ctx, run.ID.String())
		}
	}
	if f.next >= len(f.steps) {
		return ToolCall{}, errors.New("pollCancelExec: NextCall called past the end of the script")
	}
	return f.steps[f.next], nil
}

func (f *pollCancelExec) ExecuteTool(_ context.Context, _ string, _ map[string]any) (ExecuteToolResult, error) {
	f.next++
	return ExecuteToolResult{OK: true}, nil
}

func TestExecutor_CancelRun_MidLoop_ViaFlagPolledAtIterationTop(t *testing.T) {
	fake := &pollCancelExec{
		steps: []ToolCall{
			{ToolName: "search_documents", Args: map[string]any{}, TokensUsed: 1},
			{ToolName: "search_documents", Args: map[string]any{}, TokensUsed: 1},
		},
	}
	f := newHITLTestExecutor(t, fake, 10)
	fake.cancel = f.cancel

	execSeedTemplate(t, f.pool, "hitl-cancel-midloop-tmpl", "clio", "specialist", []string{"search_documents"})
	orgID, agentID := uuid.New(), uuid.New()
	execSeedAgent(t, f.pool, orgID, agentID, "hitl-cancel-midloop-tmpl", 100000, 25, 300)

	ctx := execTenantCtx(orgID, uuid.New())
	run, err := f.ex.CreateRun(ctx, CreateRunInput{AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`)})
	require.NoError(t, err)
	require.NotNil(t, run.TerminatedReason)
	require.Equal(t, "user_canceled", *run.TerminatedReason)
}

// failingNextCallExec's NextCall always errors, simulating an infra-level
// failure (e.g. a downstream dial failure) mid-loop — a path that bypasses
// finalize entirely, since runLoop returns the error directly rather than
// reaching a terminated_reason.
type failingNextCallExec struct{}

func (failingNextCallExec) NextCall(_ context.Context, _ repo.AgentsAgentRun, _ int) (ToolCall, error) {
	return ToolCall{}, errors.New("failingNextCallExec: simulated infra failure")
}

func (failingNextCallExec) ExecuteTool(_ context.Context, _ string, _ map[string]any) (ExecuteToolResult, error) {
	return ExecuteToolResult{}, errors.New("failingNextCallExec: ExecuteTool should never be reached")
}

// TestExecutor_CreateRun_InfraErrorMidLoop_ReleasesSemaphoreSlot proves the
// fix for the semaphore-leak bug: an infra-level error from NextCall
// bypasses finalize (which is the only place that used to release the
// slot), so without runLoopReleasingSemOnError the org's concurrency slot
// would stay acquired forever — there is no TTL to reclaim it.
func TestExecutor_CreateRun_InfraErrorMidLoop_ReleasesSemaphoreSlot(t *testing.T) {
	f := newHITLTestExecutor(t, failingNextCallExec{}, 1)

	execSeedTemplate(t, f.pool, "hitl-infra-error-tmpl", "clio", "specialist", []string{"search_documents"})
	orgID, agentID := uuid.New(), uuid.New()
	execSeedAgent(t, f.pool, orgID, agentID, "hitl-infra-error-tmpl", 100000, 25, 300)

	ctx := execTenantCtx(orgID, uuid.New())
	_, err := f.ex.CreateRun(ctx, CreateRunInput{AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`)})
	require.Error(t, err)

	require.Equal(t, int64(0), f.sem.counts[orgID.String()])

	// The freed slot is immediately usable by a fresh run for the same org.
	ok, err := f.sem.Acquire(context.Background(), orgID.String(), 1)
	require.NoError(t, err)
	require.True(t, ok)
}


