package execution

import (
	"context"

	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// NoopToolExecutor is a placeholder ToolExecutor that immediately signals
// Done=true on its first NextCall — every run it drives terminates
// "completed" with zero iterations. It exists solely so cmd/server/main.go
// can construct a real *Executor and let the service boot before a real,
// gRPC-backed ToolExecutor (dialing a vertical service's
// ToolExecutorService, e.g. clio-svc) exists. That real implementation is
// out of scope for #1928 and lands in a later issue.
type NoopToolExecutor struct{}

// NextCall always reports the run as done.
func (NoopToolExecutor) NextCall(_ context.Context, _ repo.AgentsAgentRun, _ int) (ToolCall, error) {
	return ToolCall{Done: true}, nil
}

// ExecuteTool is never called by CreateRun's loop for a NoopToolExecutor
// (NextCall always returns Done=true first), but is implemented to
// satisfy ToolExecutor.
func (NoopToolExecutor) ExecuteTool(_ context.Context, _ string, _ map[string]any) (ExecuteToolResult, error) {
	return ExecuteToolResult{OK: true}, nil
}



